    /**
     * Tests getting all FeatureSets.
     *
     * @return    Collection
     */
    public List<FeatureSet> testGetAll() throws Throwable {
    LOGGER.info( "FeatureSetTest:testGetAll() - Retrieving Collection of FeatureSets:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all FeatureSet : " );
    List<FeatureSet> collection  = null;

    try {
        // call the static get method on the FeatureSetService
        collection = service.getAllFeatureSet();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            FeatureSet currEntity  = null;
            Iterator<FeatureSet> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getFeatureSetId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

